class MovinCube {
  constructor(_size, _iter, _palette) {
    this.size = _size;
    this.iter = _iter;
    this.col = _palette[_iter % _palette.length]
    this.pos = floor(random(4));
    this.child = null;
    if (_iter > 1) {
      this.child = new MovinCube(_size * 0.5, _iter-1, _palette);
    }
  }

  update(move = null) {
    if (!this.child) return this.move(move);

    if (this.child.update(move)) {
      this.child.move(this.counterMove(move))
      return this.move(move)
    }
  }

  counterMove(move) {
    if (move === 0) return 2;
    if (move === 1) return 3;
    if (move === 2) return 0;
    if (move === 3) return 1;
  }

  move(move) {
    let parentMoveToo = true;

    // up
    if (move === 0 && (this.pos === 1 || this.pos === 2)) {
      this.pos = this.pos === 1 ? 0 : 3;
      parentMoveToo = false;
    }
    // right
    if (move === 1 && (this.pos === 2 || this.pos === 3)) {
      this.pos = this.pos === 3 ? 0 : 1;
      parentMoveToo = false;
    }
    // down
    if (move === 2 && (this.pos === 0 || this.pos === 3)) {
      this.pos = this.pos === 0 ? 1 : 2;
      parentMoveToo = false;
    }
    // left
    if (move === 3 && (this.pos === 0 || this.pos === 1)) {
      this.pos = this.pos === 0 ? 3 : 2;
      parentMoveToo = false;
    }

    return parentMoveToo;
  }

  show(t = false) {
    const sze2 = this.size * 0.5;
    const dx = this.pos == 0 || this.pos == 1 ? sze2 : -sze2;
    const dy = this.pos == 1 || this.pos == 2 ? sze2 : -sze2;
    if (t) translate(dx, dy)
    fill(this.col)
    rect(0, 0, this.size, this.size)

    if (this.child) this.child.show(true);
  }
}

